typedef struct {
    int used;
    int size;
    int payload[4];
} Block;

int pool_alloc(Block pool[], int n, int size) {
    for (int i = 0; i < n; i++) {
        if (pool[i].used == 0 && pool[i].size >= size) {
            pool[i].used = 1;
            return i;
        }
    }
    return -1;
}

int pool_free(Block pool[], int n, int index) {
    if (index < 0 || index >= n) return 0;
    if (pool[index].used == 0) return 0;
    pool[index].used = 0;
    return 1;
}

int main() {
    Block pool[3] = {{0, 4}, {0, 8}, {0, 2}};
    int a = pool_alloc(pool, 3, 4);
    int b = pool_alloc(pool, 3, 8);
    int c = pool_alloc(pool, 3, 8);
    printf("a=%d b=%d c=%d\n", a, b, c);

    pool[b].payload[0] = 42;
    printf("payload=%d\n", pool[b].payload[0]);

    int first = pool_free(pool, 3, b);
    int again = pool_free(pool, 3, b);
    printf("free=%d double_free=%d\n", first, again);

    int reuse = pool_alloc(pool, 3, 8);
    printf("reuse=%d\n", reuse);
    return 0;
}

