struct Node *remove_value(struct Node *head, int value) {
    struct Node *prev = NULL;
    struct Node *cur = head;
    while (cur != NULL) {
        if (cur->value == value) {
            if (prev == NULL) return cur->next;
            prev->next = cur->next;
            return head;
        }
        prev = cur;
        cur = cur->next;
    }
    return head;
}

