struct Stack {
    int data[5];
    int top;
};

void stack_init(struct Stack *s) {
    s->top = 0;
}

int push(struct Stack *s, int value) {
    if (s->top >= 5) return 0;
    s->data[s->top] = value;
    s->top++;
    return 1;
}

int pop(struct Stack *s, int *out) {
    if (s->top <= 0) return 0;
    s->top--;
    *out = s->data[s->top];
    return 1;
}

int main() {
    struct Stack s;
    stack_init(&s);
    push(&s, 10);
    push(&s, 20);
    push(&s, 30);

    int v = 0;
    printf("pop=%d\n", pop(&s, &v));
    printf("value=%d top=%d\n", v, s.top);
    printf("peek=%d\n", s.data[s.top - 1]);
    return 0;
}

struct Queue {
    int data[4];
    int head;
    int count;
};

void queue_init(struct Queue *q) {
    q->head = 0;
    q->count = 0;
}

int enqueue(struct Queue *q, int value) {
    if (q->count >= 4) return 0;
    int tail = (q->head + q->count) % 4;
    q->data[tail] = value;
    q->count++;
    return 1;
}

int dequeue(struct Queue *q, int *out) {
    if (q->count <= 0) return 0;
    *out = q->data[q->head];
    q->head = (q->head + 1) % 4;
    q->count--;
    return 1;
}

int main() {
    struct Queue q;
    queue_init(&q);
    enqueue(&q, 1);
    enqueue(&q, 2);
    enqueue(&q, 3);

    int v = 0;
    printf("first=%d\n", dequeue(&q, &v));
    printf("value=%d\n", v);
    enqueue(&q, 4);
    enqueue(&q, 5);

    int first = 1;
    while (dequeue(&q, &v)) {
        if (!first) printf(" ");
        printf("%d", v);
        first = 0;
    }
    printf("\nhead=%d count=%d\n", q.head, q.count);
    return 0;
}

