    // 用数组当栈，遇到左括号入栈，右括号与栈顶匹配
    return 1;
}

exercise.solution:
int brackets_ok(char *s) {
    char stack[64];
    int top = 0;
    while (*s != 0) {
        char c = *s;
        if (c == '(' || c == '[' || c == '{') {
            if (top >= 64) return 0;
            stack[top] = c;
            top++;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) return 0;
            char open = stack[top - 1];
            top--;
            if (c == ')' && open != '(') return 0;
            if (c == ']' && open != '[') return 0;
            if (c == '}' && open != '{') return 0;
        }
        s++;
    }
    return top == 0;
}

