} Student;

int total_score(Student s[], int n) {
    int total = 0;
    for (int i = 0; i < n; i++) total += s[i].score;
    return total;
}

int find_max(Student s[], int n) {
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (s[i].score > s[best].score) best = i;
    }
    return best;
}

int find_min(Student s[], int n) {
    int worst = 0;
    for (int i = 1; i < n; i++) {
        if (s[i].score < s[worst].score) worst = i;
    }
    return worst;
}

int pass_count(Student s[], int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (s[i].score >= 60) count++;
    }
    return count;
}

int grade_index(int score) {
    if (score >= 90) return 0;
    if (score >= 80) return 1;
    if (score >= 70) return 2;
    if (score >= 60) return 3;
    return 4;
}

int main() {
    Student s[6] = {
        {101, "Ann", 92},
        {102, "Bob", 58},
        {103, "Cid", 76},
        {104, "Dan", 60},
        {105, "Eve", 85},
        {106, "Fay", 85}
    };
    int n = 6;
    int total = total_score(s, n);
    int hi = find_max(s, n);
    int lo = find_min(s, n);
    int count[5];
    for (int i = 0; i < 5; i++) count[i] = 0;
    for (int i = 0; i < n; i++) {
        int g = grade_index(s[i].score);
        count[g]++;
    }
    printf("total=%d avg=%.1f\n", total, total * 1.0 / n);
    printf("max=%s(%d) min=%s(%d)\n", s[hi].name, s[hi].score, s[lo].name, s[lo].score);
    printf("pass=%d rate=%.1f%%\n", pass_count(s, n), pass_count(s, n) * 100.0 / n);
    printf("A=%d B=%d C=%d D=%d F=%d\n", count[0], count[1], count[2], count[3], count[4]);
    return 0;
}

typedef struct {
    int id;
    char name[12];
    int score;
} Student;

void sort_by_score(Student s[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            int swap = s[j].score < s[j + 1].score;
            if (s[j].score == s[j + 1].score && s[j].id > s[j + 1].id) swap = 1;
            if (swap) {
                Student t = s[j];
                s[j] = s[j + 1];
                s[j + 1] = t;
            }
        }
    }
}

char grade_of(int score) {
    if (score >= 90) return 'A';
    if (score >= 80) return 'B';
    if (score >= 70) return 'C';
    if (score >= 60) return 'D';
    return 'F';
}

int main() {
    Student s[6] = {
        {105, "Eve", 85},
        {101, "Ann", 92},
        {104, "Dan", 60},
        {102, "Bob", 58},
        {103, "Cid", 76},
        {106, "Fay", 85}
    };
    int n = 6;
    sort_by_score(s, n);
    printf("%-4s %-6s %5s %5s\n", "rank", "name", "score", "grade");
    int rank = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || s[i].score != s[i - 1].score) rank = i + 1;
        printf("%-4d %-6s %5d %5c\n", rank, s[i].name, s[i].score, grade_of(s[i].score));
    }
    return 0;
}

