exercise.solution:
typedef struct {
    int id;
    char name[12];
    int score;
} Student;

int better(Student a, Student b) {
    if (a.score != b.score) return a.score > b.score;
    return a.id < b.id;
}

int top_n(Student s[], int n, int k, Student out[]) {
    if (k <= 0 || n <= 0) return 0;
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (m < k) {
            int pos = m;
            while (pos > 0 && better(s[i], out[pos - 1])) {
                out[pos] = out[pos - 1];
                pos--;
            }
            out[pos] = s[i];
            m++;
        } else if (better(s[i], out[k - 1])) {
            int pos = k - 1;
            while (pos > 0 && better(s[i], out[pos - 1])) {
                out[pos] = out[pos - 1];
                pos--;
            }
            out[pos] = s[i];
        }
    }
    return m;
}
